window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b6e601c55a7e27f7"]={"versions": [{"id": "FIG-b6e601c55a7e27f7", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Metamodell-Ausschnitt für die AUTOSAR-Konfiguration des Moduls Watchdog Manager (WdgM). Das Diagramm spezifiziert die Struktur des Konfigurationscontainers <code>WdgMActivationGpt</code> und dessen Verknüpfung mit dem externen Modul GPT (General Purpose Timer) im Kontext der Konfigurationsvariante <code>VARIANT-POST-BUILD</code> (Post-build time).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>WdgMActivationGpt</strong> (<code>ParamConfContainerDef</code>): Konfigurationscontainer des WdgM ohne untergeordnete Sub-Container (<code>No Included Containers</code>). Besitzt zwei Kompositionsbeziehungen:</li>\n<li><code>+parameter</code>: Aggregiert den ganzzahligen Parameter <code>WdgMGptCycle</code> vom Typ <code>IntegerParamDef</code> mit dem Attribut <code>min = 1</code>.</li>\n<li><code>+reference</code>: Aggregiert die symbolische Referenz <code>WdgMGptChannelRef</code> vom Typ <code>SymbolicNameReferenceParamDef</code>.</li>\n<li><strong>WdgMGptChannelRef</strong>: Referenziert über eine gerichtete Assoziation (<code>+destination</code>) den externen Zielcontainer <code>GptChannelConfiguration</code> (<code>ParamConfContainerDef</code>) aus dem Modul GPT (<code>(from GPT)</code>).</li>\n<li><strong>GptChannelConfiguration</strong>: Externer Ziel-Container mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>. Enthält per Komposition (<code>+parameter</code>) den Parameter <code>GptChannelId</code> vom Typ <code>IntegerParamDef</code> mit <code>symbolicNameValue = true</code> und <code>min = 0</code> (<code>(from GPT)</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Laufzeitsequenzen. Es definiert die Parametrierung zur Aktivierung/Triggerung des Watchdog Managers über periodische GPT-Timer-Kanäle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der AUTOSAR-WdgM-Konfiguration für GPT-Aktivierungsquellen. Der Container <code>WdgMActivationGpt</code> unterliegt der Anforderung bzw. Abhängigkeit <code>WDGM193</code> und ist im Post-Build-Zeitpunkt konfigurierbar (<code>VARIANT-POST-BUILD</code>). Bei der Systemkonfiguration muss <code>WdgMGptChannelRef</code> zwingend auf eine gültige <code>GptChannelConfiguration</code> verweisen, deren ganzzahliger <code>GptChannelId</code> als symbolischer Name aufgelöst wird; <code>WdgMGptCycle</code> erzwingt einen Mindestwert von 1.</p>"}, {"id": "FIG-8949640176e5c9d5", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Metamodell-Ausschnitt für die AUTOSAR-Konfiguration des Moduls Watchdog Manager (WdgM). Das Diagramm spezifiziert die Struktur des Konfigurationscontainers <code>WdgMActivationGpt</code> und dessen Verknüpfung mit dem externen Modul GPT (General Purpose Timer) im Kontext der Konfigurationsvariante <code>VARIANT-POST-BUILD</code> (Post-build time).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>WdgMActivationGpt</strong> (<code>ParamConfContainerDef</code>): Konfigurationscontainer des WdgM ohne untergeordnete Sub-Container (<code>No Included Containers</code>). Besitzt zwei Kompositionsbeziehungen:</li>\n<li><code>+parameter</code>: Aggregiert den ganzzahligen Parameter <code>WdgMGptCycle</code> vom Typ <code>IntegerParamDef</code> mit dem Attribut <code>min = 1</code>.</li>\n<li><code>+reference</code>: Aggregiert die symbolische Referenz <code>WdgMGptChannelRef</code> vom Typ <code>SymbolicNameReferenceParamDef</code>.</li>\n<li><strong>WdgMGptChannelRef</strong>: Referenziert über eine gerichtete Assoziation (<code>+destination</code>) den externen Zielcontainer <code>GptChannelConfiguration</code> (<code>ParamConfContainerDef</code>) aus dem Modul GPT (<code>(from GPT)</code>).</li>\n<li><strong>GptChannelConfiguration</strong>: Externer Ziel-Container mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>. Enthält per Komposition (<code>+parameter</code>) den Parameter <code>GptChannelId</code> vom Typ <code>IntegerParamDef</code> mit <code>symbolicNameValue = true</code> und <code>min = 0</code> (<code>(from GPT)</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Laufzeitsequenzen. Es definiert die Parametrierung zur Aktivierung/Triggerung des Watchdog Managers über periodische GPT-Timer-Kanäle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der AUTOSAR-WdgM-Konfiguration für GPT-Aktivierungsquellen. Der Container <code>WdgMActivationGpt</code> unterliegt der Anforderung bzw. Abhängigkeit <code>WDGM193</code> und ist im Post-Build-Zeitpunkt konfigurierbar (<code>VARIANT-POST-BUILD</code>). Bei der Systemkonfiguration muss <code>WdgMGptChannelRef</code> zwingend auf eine gültige <code>GptChannelConfiguration</code> verweisen, deren ganzzahliger <code>GptChannelId</code> als symbolischer Name aufgelöst wird; <code>WdgMGptCycle</code> erzwingt einen Mindestwert von 1.</p>"}], "trans": [{"from": "FIG-b6e601c55a7e27f7", "to": "FIG-8949640176e5c9d5", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
